package com.zest.products.product;
import jakarta.persistence.*;
@Entity @Table(name="item",indexes=@Index(name="idx_item_product_id",columnList="product_id")) public class Item { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(nullable=false) private int quantity; public Long getId(){return id;} public Product getProduct(){return product;} public void setProduct(Product p){product=p;} public int getQuantity(){return quantity;} public void setQuantity(int q){quantity=q;} }
